<?php
namespace Database\Seeders; use Illuminate\Database\Seeder; use App\Models\{MarketplaceCategory,Announcement,Role,Permission};
class DatabaseSeeder extends Seeder {public function run():void {foreach(['Electronics','Fashion','Home','Beauty'] as $i=>$name) MarketplaceCategory::firstOrCreate(['slug'=>strtolower($name)],['name'=>$name,'sort_order'=>$i]);Announcement::firstOrCreate(['title'=>'Welcome to ChatCart'],['body'=>'Chat. Connect. Shop.','placement'=>'global','status'=>'published']);$roles=[];foreach(['super-admin','moderator','marketplace-manager','support','finance'] as $r)$roles[$r]=Role::firstOrCreate(['slug'=>$r],['name'=>ucwords(str_replace('-',' ',$r))]);$perms=[];foreach(['dashboard.view','users.view','users.manage','reports.view','reports.moderate','kyc.view','kyc.review','marketplace.view','marketplace.manage','orders.view','orders.manage','transactions.view','refunds.manage','notifications.send','support.manage','roles.manage','settings.manage','exports.create','audit.view'] as $p)$perms[$p]=Permission::firstOrCreate(['slug'=>$p],['name'=>$p]);$roles['super-admin']->permissions()->sync(collect($perms)->pluck('id'));$roles['moderator']->permissions()->sync(collect($perms)->only(['dashboard.view','users.view','reports.view','reports.moderate','audit.view'])->pluck('id'));$roles['marketplace-manager']->permissions()->sync(collect($perms)->only(['dashboard.view','marketplace.view','marketplace.manage','orders.view','orders.manage','kyc.view','kyc.review'])->pluck('id'));$roles['support']->permissions()->sync(collect($perms)->only(['dashboard.view','users.view','support.manage','orders.view'])->pluck('id'));$roles['finance']->permissions()->sync(collect($perms)->only(['dashboard.view','orders.view','transactions.view','refunds.manage','exports.create'])->pluck('id'));}}
